def simple_hash(key, size):
    total = 0
    for ch in key:
        total += ord(ch)
    return total % size

def poly_hash(key, size, prime=31):
    total, power = 0, 1
    for ch in key:
        total = (total + ord(ch) * power) % size
        power = (power * prime) % size
    return total

class SimpleHashTable:
    def __init__(self, capacity=8):
        self.capacity = capacity
        self.buckets = [None] * capacity
        self.size = 0

    @property
    def load_factor(self):
        return self.size / self.capacity

    def _hash(self, key):
        return hash(key) % self.capacity

    def put(self, key, value):
        if self.load_factor >= 0.75:
            self._rehash()
        idx = self._hash(key)
        self.buckets[idx] = (key, value)
        self.size += 1

    def _rehash(self):
        old = self.buckets
        self.capacity *= 2
        self.buckets = [None] * self.capacity
        self.size = 0
        for item in old:
            if item: self.put(*item)

    def get(self, key):
        idx = self._hash(key)
        if self.buckets[idx] and self.buckets[idx][0] == key:
            return self.buckets[idx][1]
        return None

class ChainingHashTable:
    def __init__(self, capacity=8):
        self.capacity = capacity
        self.buckets = [[] for _ in range(capacity)]
        self.size = 0

    def _hash(self, key):
        return hash(key) % self.capacity

    def put(self, key, value):
        idx = self._hash(key)
        bucket = self.buckets[idx]
        for i, (k, v) in enumerate(bucket):
            if k == key:
                bucket[i] = (key, value)
                return
        bucket.append((key, value))
        self.size += 1

    def get(self, key):
        idx = self._hash(key)
        for k, v in self.buckets[idx]:
            if k == key: return v
        return None

    def delete(self, key):
        idx = self._hash(key)
        for i, (k, v) in enumerate(self.buckets[idx]):
            if k == key:
                self.buckets[idx].pop(i)
                self.size -= 1
                return True
        return False

class LinearProbingHT:
    DELETED = object()

    def __init__(self, capacity=8):
        self.capacity = capacity
        self.keys = [None] * capacity
        self.values = [None] * capacity
        self.size = 0

    def _hash(self, key): return hash(key) % self.capacity

    def put(self, key, value):
        idx = self._hash(key)
        while self.keys[idx] not in (None, self.DELETED):
            if self.keys[idx] == key:
                self.values[idx] = value
                return
            idx = (idx + 1) % self.capacity
        self.keys[idx] = key
        self.values[idx] = value
        self.size += 1

    def get(self, key):
        idx = self._hash(key)
        while self.keys[idx] is not None:
            if self.keys[idx] == key and self.keys[idx] is not self.DELETED:
                return self.values[idx]
            idx = (idx + 1) % self.capacity
        return None

    def delete(self, key):
        idx = self._hash(key)
        while self.keys[idx] is not None:
            if self.keys[idx] == key:
                self.keys[idx] = self.DELETED
                self.values[idx] = None
                self.size -= 1
                return True
            idx = (idx + 1) % self.capacity
        return False

